var _compTables = [{"id":"skyships","label":"Skyship Names","die":"d100","color":"#70b8e0","entries":["The Audacious Daughter","The Laughing Sparrow","The Audacious Lantern","The Laughing Widow","The Audacious Needle","The Patient Crown","The Audacious Serpent","The Patient Gull","The Bitter Debt","The Patient Sparrow","The Bitter Hammer","The Patient Tempest","The Bitter Verdict","The Penniless Anchor","The Bitter Vow","The Penniless Daughter","The Borrowed Crown","The Penniless Fortune","The Borrowed Daughter","The Penniless Reckoning","The Borrowed Lantern","The Quiet Compass","The Borrowed Mercy","The Quiet Hammer","The Brazen Debt","The Quiet Kestrel","The Brazen Hammer","The Quiet Tempest","The Brazen Promise","The Restless Debt","The Brazen Serpent","The Restless Ghost","The Crimson Apology","The Restless Hammer","The Crimson Daughter","The Restless Serpent","The Crimson Lantern","The Sovereign Crown","The Crimson Vow","The Sovereign Ghost","The Drowned Anchor","The Sovereign Harvest","The Drowned Daughter","The Sovereign Verdict","The Drowned Debt","The Stubborn Anchor","The Drowned Hammer","The Stubborn Compass","The Errant Daughter","The Stubborn Lantern","The Errant Gull","The Stubborn Reckoning","The Errant Inheritance","The Sudden Gull","The Errant Lantern","The Sudden Hammer","The Faithless Apology","The Sudden Sparrow","The Faithless Daughter","The Sudden Wager","The Faithless Kestrel","The Thrice-Sold Fortune","The Faithless Promise","The Thrice-Sold Mercy","The Gilded Crown","The Thrice-Sold Sparrow","The Gilded Fortune","The Thrice-Sold Verdict","The Gilded Harvest","The Unrepentant Apology","The Gilded Lantern","The Unrepentant Harvest","The Hollow Debt","The Unrepentant Lantern","The Hollow Fortune","The Unrepentant Sparrow","The Hollow Mercy","The Velvet Gull","The Hollow Sparrow","The Velvet Promise","The Iron Anchor","The Velvet Reckoning","The Iron Apology","The Velvet Sparrow","The Iron Compass","The Wandering Anchor","The Iron Sparrow","The Wandering Fortune","The Last Mercy","The Wandering Sparrow","The Last Serpent","The Wandering Vow","The Last Verdict","The Wayward Fortune","The Last Widow","The Wayward Serpent","The Laughing Compass","The Wayward Tempest","The Laughing Kestrel","The Wayward Vow"]},{"id":"tavnames","label":"Tavern & Inn Names","die":"d100","color":"#c9a84c","entries":["The Borrowed Admiral","The Lucky Gull","The Borrowed Cog","The Lucky Mammoth","The Borrowed Coin","The Patched Coin","The Borrowed Lantern","The Patched Marauder","The Bottomless Admiral","The Patched Mimic","The Bottomless Cog","The Patched Pilgrim","The Bottomless Gull","The Rusted Gondola","The Bottomless Tankard","The Rusted Mammoth","The Broken Admiral","The Rusted Mermaid","The Broken Cog","The Rusted Octopus","The Broken Crow","The Salty Boatswain","The Broken Gondola","The Salty Compass","The Burnt Anchor","The Salty Pilgrim","The Burnt Boatswain","The Salty Tankard","The Burnt Crow","The Singing Boatswain","The Burnt Lantern","The Singing Crow","The Crooked Cannon","The Singing Lantern","The Crooked Dockhand","The Singing Sky-Dog","The Crooked Mimic","The Sleeping Compass","The Crooked Tankard","The Sleeping Duchess","The Drunken Cannon","The Sleeping Gull","The Drunken Kettle","The Sleeping Tankard","The Drunken Marauder","The Smiling Boatswain","The Drunken Tankard","The Smiling Mermaid","The Gilded Compass","The Smiling Mimic","The Gilded Crystal","The Smiling Pilgrim","The Gilded Kettle","The Sour Cannon","The Gilded Sky-Dog","The Sour Dockhand","The Greedy Barrel","The Sour Octopus","The Greedy Coin","The Sour Sky-Dog","The Greedy Kettle","The Thirsty Barrel","The Greedy Mimic","The Thirsty Compass","The Grinning Coin","The Thirsty Gondola","The Grinning Harpoon","The Thirsty Mimic","The Grinning Mermaid","The Three-Legged Cog","The Grinning Mimic","The Three-Legged Harpoon","The Hanged Barrel","The Three-Legged Mammoth","The Hanged Cannon","The Three-Legged Octopus","The Hanged Crystal","The Upside-Down Barrel","The Hanged Octopus","The Upside-Down Dockhand","The Honest Anchor","The Upside-Down Lantern","The Honest Crystal","The Upside-Down Tankard","The Honest Mimic","The Wandering Barrel","The Honest Tankard","The Wandering Harpoon","The Last Crystal","The Wandering Marauder","The Last Octopus","The Wandering Mimic","The Last Pilgrim","The Weeping Boatswain","The Last Sky-Dog","The Weeping Cog","The Lucky Compass","The Weeping Coin","The Lucky Crystal","The Weeping Gondola"]},{"id":"travel","label":"Sky-Travel Complications","die":"d100","color":"#80c080","entries":["Stowaway discovered in the cargo hold — three days out, half-starved, and lying about why.","The drinking water has gone green. Someone has to figure out what got in the cistern.","A rival ship matches course and speed at long range. It never closes. It never leaves.","Navigator’s charts disagree with the isle on the horizon. One of them is wrong.","Rats — except they’re too organized, and they’ve only chewed through one specific crate.","A crewmate’s pet escapes into the rigging. It is faster, smarter, and angrier than expected.","Dead calm. Three days of it. Rations were budgeted for two.","The bilge pumps run constantly but no one can find the leak.","A passenger offers triple fare to skip the next scheduled port. They won’t say why.","Distress flare two points off the bow. The wreck looks a decade old. The flare didn’t.","Crewman wins big at dice; by morning half the crew owes him and morale is curdling.","Sails fouled by an enormous web strung between two floating rocks. Recently strung.","The compass crystal points wrong near a particular isle — every chart marks it, no chart says why.","Customs cutter signals heave-to for inspection. Cargo is legal. The forged manifest from two jobs ago is still in the chart drawer.","Cook quits, citing the thing he saw in the flour barrel. There is nothing in the flour barrel.","A floating corpse in the lane ahead — fresh, well-dressed, with a sealed letter sewn into the coat.","Two crew claim the same hammock, the same coin pouch, and increasingly the same grudge.","Birdstrike shatters the forward lantern. The birds keep coming. They aim for lights.","Anchor line snags something far below the cloudfloor. Something pulls back, once, hard.","A small isle on the route isn’t on any chart. It has a dock. The dock has fresh rope.","The ship’s boy saw another vessel “with no crew on deck at all” shadowing through last night’s fog.","Cargo shifts in a gust; a sealed crate splits open. The contents do not match the manifest.","A paying passenger turns out to be fluent in the crew’s private hand-signals. Says nothing about it. Watches.","Half the crew falls sick after a port meal. The other half ate the same thing.","A mast fitting installed at the last refit is the wrong gauge. Discovered at the worst altitude.","Lookout spots a Silver Sword patrol pennant — flying from a hull that is very much not Silver Sword.","The wind carries music. There is no isle within forty miles.","Crewman’s tattoo, glimpsed while hauling line, matches a bounty notice from the last port.","A sealed harbor letter was supposed to be delivered three ports ago. It is still aboard. It is starting to smell of lamp oil.","Fresh scratch marks on the outside of the hull. Below the waterline of any dock.","A fairy stows away in the galley and considers the ship hers now. The ship’s luck objectively improves. So do the thefts.","Charge crystals drain twice as fast along one stretch of lane. Local pilots shrug: “everyone knows about that bit.”","A passenger dies of natural causes mid-voyage. Their luggage is full of other people’s letters.","The figurehead is weeping sap. The ship’s timbers came from somewhere they shouldn’t have.","A signal mirror flashes from an uninhabited isle: proper naval code, asking for the ship’s name. Twice.","Storm forces an unplanned anchorage at an isle the bosun visibly does not want to revisit.","A crate marked PERISHABLE in the hold has been ticking for two days.","Mid-watch, the helmsman swears the stars rearranged. The navigator’s readings agree with him.","A second ship’s anchor and chain, snapped, dangle from a drifting rock — recently, violently snapped.","A whale-sized shadow passes under the cloudfloor below, pacing the ship for an hour.","The new hire works hard, fights well, and signed aboard under a name the quartermaster just found crossed out in an old crew ledger.","Port fees doubled overnight at the destination. Something happened there. Nobody on the wind knows what yet.","One lifeboat is missing. The davits were cut, not unshackled. No one is missing. Yet.","A merchant convoy ahead offers to pay for escort through “the rough patch.” Their last escort is conspicuously absent.","The ship’s cat refuses to go below decks. Has refused for three days. Cats know.","A bottle message hauled up with the catch names the ship — by its new name, given only last month.","Pirates demand toll at a chokepoint: modest, businesslike, with receipts. Refusing is the expensive option.","A hold timber bears fresh carving from the inside: a tally. Seventeen marks. The hold was empty all crossing.","The destination harbor is full — every berth, every mooring. Half the Isles seem to have had the same idea. Why?","A crewmate inherited a map mid-voyage by mail packet. By evening, three others have offered to buy it. None of them have seen it.","Fractal drizzle catches the ship with the cannon crystals slotted. They’re draining. Unload them or lose them.","A young Marauder-spawn mimic has infiltrated the hold disguised as a barrel. It is homesick and bad at its job.","The wind dies precisely whenever the ship makes more than six knots. Tested. Confirmed. Inexplicable.","Quartermaster finds the rum diluted. The watered casks were sealed in port — by the supplier on the harbor master’s list.","A passing ship requests a doctor by signal flag. Their deck is crowded. Nobody on it is moving.","Lightning strike fuses the spare crystals into one beautiful, useless lump worth a fortune to an Embercliff collector.","The bosun’s whistle echoes back from a clear sky, two seconds late, all watch.","A government courier requisitions the fastest route under crown authority. Papers immaculate. The ink still wet.","A floating garden isle has drifted across the lane. It’s lovely. It’s also claimed, and the claimant is armed.","Sail seamstress finds every spare canvas mis-cut. Sabotage at the chandler, or aboard?","Below-decks gambling has escalated to a crewman betting his contract. The winner intends to collect.","The ship answers helm a half-second slow since the last refit. The shipwright’s yard is two duchies behind.","Dock fever symptoms in the fo’c’sle: harmless, except quarantine flags at the destination mean two weeks at anchor.","A salvage beacon’s legal claim-marker floats in the lane — placed around cargo that is plainly still aboard a living ship.","Cabin boy found the captain’s second logbook. He can’t read. He’s learning fast.","An albatross lands on the mainmast and will not leave. The Giants aboard treat this as enormously significant.","Wind out of the east smells of burning. Eastmarch is always burning. This is closer.","The ship’s papers list one more crew berth than the ship has ever had. Pay has been drawn on it for years.","A drifting rock in the lane bears a fresh signal fire, neatly banked to burn through tonight. No one around.","Both anchors drag in good holding ground. Divers report the holding ground is moving.","A fellow captain at the last port asked the route, casually. His ship cleared harbor an hour before yours.","Mid-crossing, every clock and hourglass aboard disagrees. The error grows with altitude.","A crate of rescue doves was loaded instead of the message doves. They have opinions about the rigging.","The first mate received a letter at the last port and has reorganized the watch rotation around being awake at moonset.","An old patch in the hull, original to the ship, has begun seeping warm air.","A passenger’s luggage is exactly — exactly — the weight of a person.","Sky-current shifts early this season; the planned route now fights a headwind the whole way. Reroute or burn crystals.","A child stowaway claims to be an Ducal heir. The jewelry supports it. The accent doesn’t.","Last port’s grain delivery included a sealed jar addressed to a crewman who died two years ago.","The lookout’s glass shows a city on a distant isle that the charts insist is bare rock. By the time others look: bare rock.","A Jade Collection courier offers handsome payment for discreet carriage of a small box. It must never be opened, shaken, or warmed.","Crew superstition has fixated on a new hire as cursed. The hire’s record is spotless. The incidents keep happening near her anyway.","A naval requisition notice at the last port listed this ship’s class for “voluntary” charter. The patrol ahead has a boarding ladder ready.","The galley fire will not go out. Not dangerous. Just — will not go out.","A becalmed ship signals for a tow. Mid-tow, she rides far too light for her declared cargo of stone.","Someone repainted the ship’s name overnight. Same name. Better handwriting. Nobody owns up.","A wave of warmth rolls through the air at altitude — pleasant, wrong, and moving against the wind.","The chart’s pirate-warning markers along this lane were drawn in three different decades. The newest is dated next month.","A flock of message birds passes overhead, all on the same heading, all unbanded.","Ship’s carpenter finds a void behind a bulkhead: a hidden compartment, empty except for one woman’s boot and a customs seal from another duchy.","A sky-funeral barge drifts off the lane, lanterns lit, mourners absent, casket open and empty.","Storm damage exposes the keel-rune. The shipwright’s mark on it belongs to a yard that burned down before this ship was built.","A becalmed pleasure yacht hails: aristocrats, out of food, out of crystal charge, and out of patience. Rich, rude, and rescue-liable.","The wind tastes of salt. The Isles have no sea. The old Elemental deckhand has stopped talking.","Quartermaster’s tally says the hold holds more than was loaded. Recount confirms. The extra crates match no manifest and every lock.","The morning watch reports the moon set twice. The log, in two different hands, agrees.","A patrol cutter’s wreck on a drifting rock, picked clean — except the strongbox, untouched, with the key in the lock.","Mid-voyage, every crewmember’s knife is found driven into the mainmast in a neat ring. All deny it. All slept.","The ship arrives. The destination isle is gone — not destroyed: absent, with clean sky where it was, and one other ship circling the empty air, signaling frantically."]},{"id":"rumors","label":"Tavern Rumors & Dockside Gossip","die":"d100","color":"#d090e0","entries":["A dockhand swears the Silver Sword posted, then quietly removed, a bounty on a ship that doesn’t exist in any registry.","Word is the Jade Collection is paying triple for pre-Sundering coins this season. No one knows what changed.","Somebody’s little brother signed onto a Marauder crew and sends money home now. More than a magistrate makes.","They say a Golden Order patrol burned a chapel on a no-name isle last month. The Order says there was no chapel. The isle says there was no patrol.","A drunk navigator keeps buying rounds with the same story: an isle that wasn’t there on the way out and was on the way back.","The harbor master’s clerk has started wearing gloves. Indoors. In summer.","Grain prices in two duchies moved the same direction on the same day. The merchants’ guild calls it coincidence, loudly.","A Silver Hand mage came through last week asking about local storms — dates, headings, and who survived them.","They’re saying the Nightshade Manors had a wedding. Nobody says which families. Everyone lowers their voice anyway.","A salvager pulled up a ship’s bell from below the cloudfloor with a casting date eleven years from now.","The bounty on the pirate Redwake doubled overnight, and the new notice misspells her name the way only her old crew did.","Talk in the chandlery: charge crystals from one particular Embercliff workshop are lasting twice as long. The workshop denies making them.","An old woman at the fish stall says the rain fell downward over the eastern shallows for a full minute. Her granddaughter confirms it. They are not selling anything.","They say a noble house is quietly buying every old map of the southern reaches — bad maps, wrong maps, especially the wrong ones.","A whole crew walked off a ship at dock and none of them will say why, and all of them found new berths within a day.","Somebody is paying dock children to count which ships leave at night. Paying well. Paying in capital-minted coin.","The lighthouse keeper three isles over hasn’t lit the lamp in a week, but ships keep arriving safely anyway.","They’re saying a Vault inspector visited the assay office and left without inspecting anything. The assayer retired the next morning.","A Marauder was seen flying mourning colors. Pirates argue about what that means. Old pirates don’t argue; they just go quiet.","Rumor in the rigging lofts: the navy ordered new sails for ships it doesn’t have yet. Lots of them.","A tavern regular vanished mid-tab. His stool is paid through next year, in advance, by mail.","They say the Verdant Glade turned away a crown delegation at the gate-trees. Politely. The second time was less polite.","Word is a Drifthaven crew has been buying lamp oil in absurd quantities. The eternal-moonlight city, buying light.","The price of shelf-quarried stone from the Shallows tripled, and the quarry’s ledger is sealed by ducal order.","A dock preacher keeps predicting storms two days early. Right every time. He says he reads it in the gulls. The gulls have started following him.","Somebody saw a Silver Cross surgeon paying off a body collector. Or a body collector paying off a surgeon. The argument is the rumor.","They’re saying a courier route through the northern lanes lost three birds in a row — and the fourth came back with someone else’s message.","A retired bosun insists a naval cutter towed a black, windowless barge through here at midnight. The harbor log shows no traffic.","Apprentices gossip that the runesmith’s guild failed its own certification this year and the results were sealed.","The crab-boats won’t work the western shelf anymore. Ask why and you buy the next round; ask twice and you drink alone.","They say a Capital house’s third son took the grey and joined the Silver Cross. They say his family’s debts vanished the same week.","A new tavern opened on the smugglers’ row with too much capital and no history, and serves the best food on the isle at a loss.","Word from the fort towns: the Naharlynn garrisons drilled boarding-repulse three weeks straight. Garrisons. On land.","A pawnbroker is quietly refusing all jewelry from one particular noble house. He honors old pieces. Just nothing new.","They’re saying the last Barrier Renewal ran long. Minutes long. The officiants’ faces, they say, were wrong afterward.","Every rat left the grain warehouse on the same night. The warehouse is fine. The rats moved into the courthouse.","A first mate swears her captain takes sealed orders from a passenger who boards at no port and leaves at no port.","The fighting pits have a new champion who never bleeds. The bookmakers checked. The bookmakers paid out and closed early.","They say a survey ship mapped the same stretch of sky four times this season. Each chart came back different.","Old hands mutter that Fractal storms are arriving on schedule now. Rain shouldn’t keep appointments.","A noble’s pleasure yacht returned from the southern shallows riding heavy, and paid harbor fees in pearls.","Somebody bought every copy of last spring’s tide-almanac from every chandler on three isles. The almanac was wrong, famously. That’s the point, apparently.","They’re saying a Hand magus failed the Fourth Challenge and walked out of Azure Falls anyway. The Hand says no one has ever walked out. Both things have witnesses.","The night soil barges have been escorted lately. Armed escort. For night soil.","A street kid claims a statue in the temple plaza changed which way it faces. The temple installed a railing the next day.","Word in the counting houses: a Westfall labor contract was bought out by an anonymous party. Then a hundred more. The brokers are spooked and rich.","They say a Giant was seen at a northern fish market — buying, not trading. Paying in coin no mint will claim.","A whisper going around the gambling dens: the Nightshade collects debts in favors now, not coin, and writes nothing down.","The bird-keeper at the signal tower drinks free everywhere since he stopped sending one particular daily report. He didn’t stop. He was told to stop.","They’re saying two Ravenous Marauders met in open sky, circled each other for an hour, and parted. Ships don’t have conversations. These did.","A widow on chapel row gets a pension from a navy office that, per the navy, closed thirty years ago.","Talk at the breakwater: the eels in the under-harbor have started swimming in formation.","Word is an Eastmarch prospector filed a claim, sold it within the hour, and booked passage west before the ink dried. The buyer’s agent wore court shoes.","They say the new harbor chain was forged oversize — sized for keels no shipyard in the duchy can lay.","A taproom argument that won’t die: whether the moon was a god. An old Drifthaven hand ended it last week by walking out, and now everyone believes it.","The orphanage by the dry dock got a new roof, new stoves, and a new rule: the children don’t talk to sailors anymore.","They’re saying a customs officer opened the wrong crate and took retirement the same afternoon. Full pension. Sealed file.","A rope-walk worker swears the navy bought cable rated for triple any ship’s tonnage. “What are they mooring?” is the toast on smugglers’ row now.","Word from upcoast: a village pulled in their nets and found them full — of someone else’s nets.","They say the Glade’s mushroom folk stopped trading one specific dye last season and won’t say why, and now the capital’s fashion has quietly abandoned the color.","A deckhand who shipped on a survey run came back rich, silent, and terrified of maps.","The story in the chain lockers: a press gang took six men off the docks, and the navy says it has no press gangs, and six families get anonymous wages monthly.","They’re saying the duke’s new physician was hired the day before the duke fell ill.","A second-hand shop on temple row buys dreams. Writes them down, pays copper. The owner’s buyer pays him in silver.","Word is the pirate toll at the eastern chokepoint went down. Pirates lowering prices means pirates want traffic. Wanting traffic means—and here the teller orders another drink.","An old chart-seller insists three isles have swapped positions in his lifetime, slowly, and his charts prove it, and no one will publish them.","They say the Silver Sword’s job board cleared overnight — every posting filled or pulled. The clerks just shrug and re-pin yesterday’s notices.","The flower sellers know something. Lilies are sold out across the harbor district and nobody held a funeral.","A gondola operator on the capital run claims a passenger rode all five rings without papers, waved through at every gate, and tipped in a coin she’s afraid to spend.","They’re saying a wreck-diver found a sealed hold full of fresh water. Casked, stamped, and dated this year. The wreck is older than the duchy.","The barber on chandler’s row has started keeping a passenger manifest. Of haircuts. The Silver Sword buys him lunch weekly.","Word around the crystal exchange: someone is selling drained crystals as charged, and the assay-runes agree with the lie.","A shepherd on the high pasture swears the wind argued with itself for an hour, in two voices, in a language with too many vowels.","They say the Naharlynn ferry ran empty, on schedule, every day for a month — and the crown paid the fare for every empty seat.","A pit-fighter bought out his contract with capital coin, then bought out his trainer’s, the cook’s, and the gatekeeper’s. Then asked for a job. Same job.","Word in the sail lofts: an order came in for black canvas. Bolt after bolt. Cash. Collected at night, by polite men with soldiers’ hands.","They’re saying the southern caves sing now, low, on the new moon, and the cave-farmers have started leaving offerings they can’t explain choosing.","A clerk at the registry got drunk and said ship names are being reserved in blocks of fifty by a buyer with no address.","The crone at the end of the breakwater fixes nets and tells fortunes, and lately refuses to read for anyone shipping north, and refunds them, and that’s the part that scares people.","They say a tax assessor’s ledger listed an isle nobody can find, with a population, a harbor fee, and a paid balance.","Dock talk: the last three storms each missed the same isle. Cut around it. Weather doesn’t negotiate, but somebody’s clearly paying it.","A monastery upslope took in a guest in fine clothes who does scullery work and is guarded — discreetly, expensively, around the clock.","They’re saying the mint changed one tiny detail on the new coins, and the money-changers caught it in a day, and the mint denies any change, and the old coins trade at a premium now.","Word from a whaler’s widow: the pods are migrating early, all of them, same heading, and the Orc crews followed without finishing their contracts.","A schoolmaster was dismissed for teaching old history. The parents complained. Not about the history — about what their children started asking the priests.","They say a bounty hunter turned in her own bounty — posted on herself, by herself — and collected, and the clerk had to pay it, and the law has been arguing since.","The night watch on the east quay has doubled, and walks in fours now, and looks up more than out.","Talk at the carters’ yard: every road job heading inland pays double suddenly, provided you don’t mind loading at night and forgetting the route.","They’re saying an heirloom sword went to auction and three noble houses bid it to madness — and the winner melted it down that evening, publicly, smiling.","A ferryman claims the same passenger crosses with him every new moon, pays the same coin, and has not aged in nineteen years. The coin is always warm.","Word in the netting sheds: the admiralty bought the silence of a whole salvage crew, and one of them tattooed what he saw on the inside of his arm before signing.","They say the old fort’s well echoes back a half-second late now, and the garrison filled it in, and the echo moved to the cistern.","A merchant’s daughter eloped with a pirate, says the story. The merchant’s books say the pirate eloped with the ledgers.","The story going around the crew taverns: a ship paid off its entire crew at double rate, mid-contract, mid-ocean-of-sky, and sailed on with no one aboard. It made its next three ports on schedule.","They’re saying a chapel bell rang one note flat at the last festival and the priests replaced it within the week, and the old bell’s cart was escorted by soldiers, and bells don’t need guarding.","Word from the high lanes: a courier’s logbook clocked a tailwind home in both directions. The guild fined him for falsifying records. His bird backs him up.","A pawnshop on the low quay has a music box that plays a tune nobody recognizes, and old Elementals pay just to sit near it, and the owner has stopped winding it because of how they weep.","They say somewhere in the Isles there’s a harbor that only appears in Fractal weather, and every crew that’s docked there came back rich, and none of them came back right.","The quietest rumor of all, told only by leaning close: that somewhere in the chain of whispers, somebody pays for every rumor you’ve heard tonight — collects them, sorts them, files them — and that the going rate for a good one would surprise you."]},{"id":"jobs","label":"Job Board Contracts","die":"d100","color":"#e08866","entries":["RETRIEVAL: Lockbox from the wreck of the Pellucid Wager, last charted position enclosed. Box only. Do not inventory.","COURIER: Sealed diplomatic pouch to the capital ring-gates. Bonded carriers only. Bonus for under six days.","HUNT: Something is taking livestock off the high pastures — whole, upward, at night. Proof of kill required.","SURVEY: Chart the debris ring at the position enclosed. Sketch, sound, and DO NOT salvage.","ESCORT: Wedding party, two isles over. Hazard pay listed. Ask why hazard pay is listed.","RECOVERY: Runaway apprentice, age 15, last seen boarding a freighter. Return unharmed. Father pays; guild pays more.","GUARD: Warehouse night watch, six nights. Previous watchmen quit. Wages reflect that.","DELIVERY: Twelve crates, livestock, AIR HOLES MANDATORY, no questions clause, premium rate.","INVESTIGATION: Lighthouse keeper unresponsive ten days. Lamp still lit. Determine status.","ESCORT: Tax assessor’s circuit of four farming isles. Locals advised of escort. That’s why the escort.","SALVAGE: Legal claim purchased on a naval wreck. Recover cargo before claim expires — or before someone ignores the claim.","COURIER: One letter. One recipient. Verbal confirmation phrase required. Triple rate. Burn after reading is the recipient’s job, not yours.","PEST REMOVAL: Mimic infestation in dockside warehouse district. Bring weights, nets, and skepticism about furniture.","HUNT: Bounty, dead or alive — the forger known as Inkwrist. Last seen with new face, old habits.","ESCORT: Surveyor to the cold lanes and back. Surveyor is difficult. Bonus reflects difficulty, not danger. Mostly.","RECOVERY: Sunken bell of the old chapel, below the cloudfloor at position enclosed. Sentimental value, paid like strategic value.","GUARD: Auction house, three days, high-value lots. Discretion about the lots is part of the wage.","DELIVERY: Medicine, time-critical, plague flag port. Quarantine waiver enclosed. Read the waiver’s fine print.","INVESTIGATION: Cargo shrinkage on the southern run, three ships, same route, no break-ins. Inside job or outside problem — find which.","ESCORT: Witnesses, two, to ducal court. Opposing party has resources. Plan accordingly.","CHARTER: Naturalist requires passage to follow a migration. Six weeks. Naturalist is paying in patron’s gold and enthusiasm.","RETRIEVAL: Stolen figurehead of the merchantman Gilded Promise. The thief left a receipt. Start there.","HUNT: Rogue automaton from a workshop liquidation, last seen heading for open sky. Intact returns pay quadruple.","COURIER: Standing weekly run, mail packet between three minor isles. Boring. Reliable. Suspiciously well paid this month.","GUARD: Prisoner transfer, one, manacled, polite. Do not converse with the prisoner. The wage doubles if you can explain why afterward and triples if you can’t.","DELIVERY: One piano, tuned, intact, to a mountaintop monastery. The monks will not help carry. It’s a vow thing.","SURVEY: Storm-damage assessment of the outer farm isles for the ducal relief office. Honest counts only — both padding and trimming have been tried.","ESCORT: Pilgrim group to a shrine in contested airspace. Pacifists. They will not approve of your methods. They are paying for your methods.","RECOVERY: Father’s ashes, urn aboard an impounded ship in a rival duchy’s harbor. Paperwork possible but slow. Family prefers fast.","HUNT: Whatever holed the breakwater. Divers refused a second look. Their fee is your floor.","INVESTIGATION: Forged charge crystals entering the market through this port. Assay office cooperating. Someone in the assay office is the question.","COURIER: Living plant, root-balled, to the Verdant Glade gate-wardens. It must arrive alive. It has opinions about temperature.","GUARD: Festival security, three nights, weapons peace-bonded, troublemakers expected, arrests discouraged, creativity encouraged.","CHARTER: Theatrical troupe tour, five isles, six weeks. Cargo includes a prop dragon. The prop manifest is one line short.","DELIVERY: Window glass, forty panes, intact, across the rough lanes. Insurance declined to quote. Hence the rate.","RETRIEVAL: Logbook from the beached wreck on Gullspar Rock. Owner wants the book. Owner’s rivals want the book. The book is why it’s beached.","ESCORT: Retiring magistrate to a country estate. Thirty years of verdicts. Several parties wish to discuss old cases. Prevent the discussions.","HUNT: Sky-eel pod tangling the eastern mooring lines. Relocation preferred, the harbor master’s daughter has named them.","SURVEY: Verify or disprove an isle reported at the position enclosed. Standard rate to look. Extraordinary rate if it’s there.","RECOVERY: Cargo net, contents intact, snagged on a spire below the cloudfloor. Contents: sealed. Recovery: hazardous. Questions: declined.","COURIER: Apology, hand-delivered, verbal, memorized exactly. The sender will test you on it. The recipient may shoot the messenger; armor provided.","GUARD: Shipyard, new keel, two weeks. Sabotage attempted twice. The third attempt is expected to be better funded.","INVESTIGATION: Crewman overboard verdict contested by widow. Ship’s log immaculate. Immaculate is the problem.","DELIVERY: Bees. Forty hives, queen-right, to the orchard isles. Calm weather essential. The bees did not sign the calm weather clause.","ESCORT: Assayer carrying samples from a new claim. Claim location is the secret. Assayer talks when drunk. Keep him sober or keep him quiet.","HUNT: Bounty on the cutter Sablewind, piracy, three counts. Crew may negotiate; captain may not. The distinction is in the fine print and the captain knows it.","CHARTER: Cartographer requires slow passage along the miasma boundary. Hazard pay structured per day of survival. Read that clause again.","RETRIEVAL: Love letters, bundled, ribbon-tied, from a house about to be searched by people with worse intentions than embarrassment.","GUARD: Granary during the count. The count decides the duchy’s tax. Everyone with a thumb wants it on the scale.","COURIER: Resignation letter, to a Nightshade-adjacent counting house, from a clerk who would rather not deliver it personally. Understandable. Payable in advance, also understandable.","INVESTIGATION: The same beggar appears at three harbors a hundred miles apart on consecutive days. Someone’s ferrying him. Find out who and why.","DELIVERY: Headstone, carved, to a widow at the world’s edge of the western lanes. Paid by a name not on the stone.","ESCORT: Schoolchildren, capital scholarship cohort, eleven of them, one chaperone, four days. Veterans of this run drink free in three ports.","HUNT: Saboteur in the rigging yards. Pattern suggests training. Training suggests employer. Employer is the actual contract.","SURVEY: Soundings of the new shoal forming in the eastern approach. Forming. Shoals don’t form in sky-lanes. Hence the rate.","RECOVERY: Impounded racing sloop, fees paid in full, release papers enclosed, harbor master refusing anyway. Lawful retrieval preferred. Retrieval, regardless.","GUARD: Night escort, midwife, hill district, one month. The hill district at night is the wage explanation.","COURIER: Tooth, gold, in a velvet box, to an address that is a boat that moves. Schedule of predicted positions enclosed. Predictions are the seller’s. Caveat emptor.","CHARTER: Funeral at altitude. Family aboard, ashes scattered windward of the family estate per the will. The will is contested. The family is armed. The wind is shifty.","DELIVERY: Printing press, disassembled, unmarked crates, to a basement address, at night. Literacy is legal. This press’s output, less so.","INVESTIGATION: Who is paying the dock children to count night departures, and stop them — the paying, not the children.","HUNT: The dog. The big one. The one from the quarry. Bring the muzzle from the office. Bring friends.","ESCORT: Ducal physician on plague-flag circuit. Immunity papers cover the physician. Yours cost extra and are enclosed. Check the dates.","RETRIEVAL: One barrel, marked with a yellow band, from a warehouse that burned last night. The barrel is fine. The barrel is always fine. Hurry.","GUARD: A tree. Two weeks. The contract does not elaborate. The wage does.","COURIER: Seed packet to the agricultural office, priority seal. It rattles like seeds. It weighs like lead.","SURVEY: Census assistance, outer shepherd isles, two weeks. Count people. Some prefer not to be counted. Count them anyway, kindly.","DELIVERY: Mirror, full-length, antique, to the Selvain holdings south. Keep covered at night per the family’s standing instruction. The instruction is old. Honor it.","INVESTIGATION: Tavern brawls at the Drowned Gull, every new moon, between strangers who’ve never met and fight like they have.","HUNT: Egg poachers working the cliff rookeries. The birds are protected. The poachers, as of this posting, are not.","ESCORT: A confession. Written, sealed, walking on the legs of the man who wrote it, to a magistrate two duchies away. He goes willingly. Others prefer he not arrive.","CHARTER: Honeymoon couple, scenic route, two weeks, romance, sunsets. Groom’s former crew has expressed interest in attending. Uninvited.","RECOVERY: Ship’s cat, answers to Bosun, taken by departing crew of the Sour Kettle out of spite. The crew is dangerous. The owner’s grief is paying double.","GUARD: Counting house, audit week. The auditors fear no man. The auditors have hired you anyway.","COURIER: Weather readings, daily, from the high station to the harbor office, one month. Previous courier reported the readings “argued with him.” Position open.","DELIVERY: Bell, recast, to a chapel that requested its old bell back, not a new one. Deliver anyway. Wear something you can run in.","INVESTIGATION: Why the night soil barges have armed escorts. The poster is the escort company’s competitor. The truth is the deliverable.","HUNT: Bounty, alive only — the cartographer who sold the same secret route to four buyers. All four are co-funding this posting. He’s worth more confused than dead.","ESCORT: Crystal shipment, capital-bound, decoy convoy structure, you may be the decoy, the rate is the same either way, the survival odds are not.","SURVEY: Locate the source of the music on the western wind. Bring a musician. Bring earplugs for everyone else.","RETRIEVAL: Court gown from a seamstress holding it hostage over a disputed bill. Pay the bill. The bill is not the problem. The seamstress’s new patron is the problem.","GUARD: One night, one door, do not open the door, do not knock on the door, do not answer the door if it knocks.","CHARTER: Pilgrimage of seven Mushroom Folk to soil they will not name in a place they’ll know when they feel it. Open-ended. Funded absurdly. The High Guardian’s seal is real.","DELIVERY: Wages, monthly, to the keeper of a light that guards no charted lane. Standing crown contract. The clerk who asks questions about it gets transferred.","COURIER: Challenge, formal, written, to a duelist of reputation. Etiquette packet enclosed. Deliver with witnesses. Leave with witnesses.","INVESTIGATION: A dead man’s pension keeps getting collected. The clerk who flagged it is on leave. The leave was not her idea. Start with the clerk.","HUNT: Sky-leeches in the southern mooring field, attaching to keels, draining charge crystals through the hull. New problem. Name your method; show your results.","ESCORT: The last speaker of a dying dialect to the capital archive, with stops at every isle she asks for, in order, no matter the route. She’s saying goodbye. The archive is paying. Take the long way.","RECOVERY: Anchor of the founder’s ship from the harbor floor for the bicentennial. Ceremonial. Public. The thing wedging it down there is neither.","GUARD: Food taster’s assistant, banquet season, noble house. The taster needs someone to watch the kitchen while he watches the food. The last assistant ate something.","COURIER: A key, alone, no address — the recipient will find YOU within three days of you accepting. Payment on relinquishment. Do not duplicate it. They’ll know. They always know.","SURVEY: Wind-speed measurements inside the chokepoint during peak season. The instruments are insured. You are offered the same policy at a discount.","DELIVERY: Soup. Hot. Across the harbor. The rate is forty times standard. The address is the harbor master’s office. It is a test, an apology, or a trap — accept and learn which.","HUNT: The rumor itself: find who STARTED the story about the gold in the old fort’s well, before the next fool drowns in it. The well’s owner is the poster. The well’s owner is also, possibly, the gold’s.","ESCORT: A Marauder defector — a person who left a Marauder crew, which is not done — to a Silver Sword office, ahead of former colleagues, who feel it is not done strongly.","INVESTIGATION: The job board itself. Three postings last month led crews into ambushes. The clerk’s pins are innocent. Someone’s ink is not.","RETRIEVAL: One hundred contracts, stolen, from this office, last night — including the original of this one. If you are reading this, the thief reposted it. Come in. Talk to us. Reward stands.","GUARD: This posting is blank except for coordinates and the largest fee on the board. It has hung for a month. The clerk says it’s paid through the year. The clerk won’t meet your eye.","WANTED: Crew. Any. The poster is a ship’s name and a berth number, no employer, no terms, standard rates pre-paid into the harbor bond office. The ship is real. It’s beautiful. The previous crew left no forwarding address."]},{"id":"quirks","label":"NPC Quirks & Mannerisms","die":"d100","color":"#c9a84c","entries":["Refers to their ship, shop, or cart as \"she\" and apologizes to it when bumped.","Whistles the same four notes when thinking. Doesn’t know they do it. Denies it.","Wears one glove. The bare hand does all the work.","Quotes their grandmother constantly. The grandmother’s advice gets darker the longer you listen.","Never sits with their back to a window. Doors are fine. Windows, never.","Collects buttons. Will trade information for interesting ones.","Speaks to animals in a normal voice and to people in a slightly performed one.","Always eating sunflower seeds; the shell pile marks everywhere they’ve waited.","Laughs at danger — literally, a nervous bark of a laugh, at the worst moments.","Keeps checking a pocket watch that has clearly been broken for years.","Introduces themselves with a different middle name every time.","Smells faintly of cinnamon. No explanation is ever offered. None will be.","Folds anything paper into birds while talking: receipts, notices, your map.","Calls everyone \"captain\" regardless of rank, age, or whether they’ve sailed.","Refuses to say the number nine. Says \"eight-and-one.\" Will not discuss it.","Sketches everyone they meet in a small book. The likenesses are upsettingly good.","Ends negotiations by spitting in their palm. Is visibly hurt when others hesitate.","Hums sea-shanties at funerals and dirges at parties. Means well.","Wears a wedding ring on a cord, never the finger. Touches it before lying.","Insists on paying for the first round and never the second.","Remembers everyone’s name and one wrong fact about them, held with total confidence.","Knits while standing watch. Productive. The scarves go to people they’ve threatened.","Tastes the air before entering a room — a quick, lizardish tongue-flick. Old habit. Useful habit.","Keeps a list of people who owe them favors. Keeps it visible. Adds to it theatrically.","Apologizes before delivering bad news, good news, and the soup.","Carries a chess piece — a black knight — and sets it on the table for serious talks.","Tells you what the weather will be tomorrow, unprompted, accurately, with mild dread.","Never finishes a drink. Leaves exactly one swallow. \"For the dead,\" if pressed.","Sharpens a knife that is already sharp whenever thinking. The knife is very sharp.","Refers to events as \"before the fire\" and \"after the fire\" and assumes you know which fire.","Has named their wheelbarrow, cart mule, and cargo hook, and consults them on decisions.","Cracks every knuckle in sequence before answering hard questions. Eleven cracks. Always eleven.","Collects foreign curse words and deploys them with scholarly delight and terrible pronunciation.","Eats dessert first \"in case of pirates.\"","Stands exactly one step too close. Steps closer when corrected, apologizing.","Wears mourning grey one fixed day a week. Conducts business as usual on it. Cheerfully.","Repeats your last three words back as a question? As a question.","Keeps live crickets in a tin \"for luck.\" The tin has air holes and a name plate.","Bows to ships entering harbor. All of them. Even the ugly ones. Especially the ugly ones.","Talks themselves through tasks in third person, by their own full legal name.","Has a coin trick for every occasion and exactly one of them works.","Categorizes everyone within a minute as \"crew,\" \"cargo,\" or \"weather,\" and treats them accordingly.","Lies about small things constantly and is rigorously honest about large ones.","Wears spectacles with one cracked lens. The crack is recent. The story changes.","Touches every doorframe twice on the way through. In, two. Out, two.","Saves the wax seals from letters. Has a drawer of them, sorted by sender, including yours.","Pretends to consult dice for decisions. The dice are blank. The decision was already made.","Compliments weapons like other people compliment babies.","Always knows what time it is, to the minute, without looking, and resents being tested on it.","Carries a second hat in case of \"hat emergencies.\" Has produced it twice. Both times were emergencies.","Asks \"do you smell smoke?\" at least once a day. There is never smoke. Once, there was.","Names a price, then immediately offers a worse deal with more enthusiasm.","Cannot pass a knot without checking it. Strangers’ knots, rivals’ knots, the gallows’ knot.","Holds doors with one arm fully extended, like a salute, until everyone is through. Everyone.","Whittles small ducks. Gives them to people who are about to be in danger. Won’t confirm the correlation.","Recites prices from twenty years ago at every transaction, wounded afresh each time.","Has a scar they tell three different stories about, in rotation, all of them suspicious, none matching the scar.","Pockets sugar, bread, candle-ends — anything unwatched and small. Wealthy. Does it anyway.","Greets the morning by reading yesterday’s notice-board aloud to anyone trapped nearby.","Refuses all nicknames and bestows them on everyone else within the hour.","Keeps a \"weather eye\" shut at all times indoors, to preserve its night vision. Switches eyes weekly.","Quietly mends things in other people’s houses without asking: chairs, hinges, marriages.","Has memorized one poem and steers every conversation toward the conditions for reciting it.","Argues both sides of every question aloud, then thanks themselves for the input.","Wears every ring they’ve ever been given. Both hands. There is a story per ring. The stories interconnect.","Sits only on tables, barrels, and rails. Chairs are \"a trap.\" Won’t elaborate.","Tracks debts in chalk on their own forearm. Spits and rubs one out when settled. The left arm is nearly full.","Calls all currency \"fish.\" \"That’ll be twelve fish.\" Everyone local has stopped noticing.","Practices their signature in the air during conversations, with a flourish at your most important sentence.","Asks permission of rooms before entering them. Waits a beat. Has, twice in their life, not entered.","Cleans their boots before bad news, so as to \"meet it properly shod.\"","Keeps an obituary collection of people who wronged them. Reads it on bad days like a tonic.","Refers to the future exclusively as \"if the wind holds.\"","Snacks on raw onion like an apple while making intense, friendly eye contact.","Hands you things with both hands, like an offering, including your own change.","Has decided which of their acquaintances would survive various disasters, and will tell you your rating if asked. Don’t ask.","Carries chalk and corrects errors on public signs, menus, and wanted posters. Including the bounties. Including their own.","Stretches elaborately before lying, like an athlete before a sprint.","Sings only when it rains. Knows an unsettling number of rain songs. In Fractal weather, hums instead, with the door barred.","Wears a key on a neck-cord and touches it when maps are mentioned. There is no lock. There was a lock.","Addresses all letters aloud while sealing them, including the ones they then burn.","Cuts their food into perfect squares. All of it. The soup is a struggle and a triumph.","Claims to be retired from a different profession each week. The skills, worryingly, always check out.","Greets Giants, Marauder hulls, and large weather formally, by title. \"Good morning, Storm.\"","Keeps a tally of sunrises seen from altitude versus ground, and is twelve behind on a private quota.","Refuses to whistle aboard ship, glares at those who do, and won’t explain — but the old hands all nod along.","Wears an empty scabbard, beautifully maintained. Asking what happened to the blade costs a drink and buys a different answer every time.","Files everyone they meet under a profession they \"would have been good at.\" Tells them. Is usually right. Was once devastatingly right.","Smiles before fights — not menacingly; with genuine relief, like the weather finally broke.","Folds their hands and waits through interruptions, however long, then resumes their sentence at the exact word.","Takes the temperature of every harbor — actually, with an instrument — and logs it in a book labeled EVIDENCE.","Picks a \"lucky stranger\" each morning and quietly does them three small favors before dusk. Today it might be you.","Always faces the wind when making promises so the words \"get carried.\" Turns you by the shoulders to face it too.","Has prepared last words. Updates them seasonally. Solicits feedback on drafts.","Keeps caramels in every pocket, coat, and pouch — for children, hostages, and tense negotiations, in that order of effectiveness.","Won’t step on ship shadows. Crosses the dock in zigzags on busy mornings. Has never once been crushed by anything falling, and cites this.","Reads strangers’ palms uninvited, refuses payment, and is only ever interested in one line, and won’t say which.","Ends every meeting, sale, and argument the same way: \"Fair winds, and don’t tell anyone where you heard that.\"","Has no quirks whatsoever — unsettlingly composed, perfectly average, utterly unmemorable. People describe them differently every time. That IS the quirk, and somebody trained it into them."]},{"id":"cargo","label":"Cargo Manifests","die":"d100","color":"#a87040","entries":["Crated window glass for the new chapel, packed in wool, insured for triple its value.","Westfall grain, ducal seal, escort-mandatory grade. The seal is real. Check anyway.","Two hundred charge crystals, drained, returning for refill. Worth little. Stolen constantly anyway.","A nobleman’s wine cellar, relocating. The good crates are marked. The marks are lies; the butler’s system is the truth.","Bolts of jade-dyed silk, Glade certificates attached, fashion-season deadline approaching.","Mining timber for Eastmarch shafts, cut overlong per the buyer’s odd specification.","One racehorse, sedated, hating it. Groom included, also sedated, by choice.","Mail packet: four hundred letters, one of which is the reason this run pays double.","Anvils. Just anvils. The hold rides low and the ship handles like an argument.","A printing press marked AGRICULTURAL EQUIPMENT in handwriting too careful by half.","Live crabs, southern shallows stock, in tanks. The tanks need cycling every six hours. The crabs have learned the schedule.","Theatrical scenery: a castle, flat-packed. A throne, real. A crown, definitely fake, guarded like it isn’t.","Spice tins from the eastern routes, every tenth tin heavier than its fellows.","Ship’s biscuit, navy contract, fresh-baked. The phrase \"fresh-baked\" appears nowhere in the contract.","A disassembled gondola car, capital-bound for repair, with a Ring-stamped travel writ worth more than the cargo.","Beeswax candles, temple-grade, packed nose-high in honey scent. Stowaways find this hold first.","Three crates labeled BOOKS, weight consistent with books, sealed by a Silver Hand courier office.","Replacement bell for a fort-town chapel. The old bell rides home in the same hold, wrapped, facing the wall.","Whale oil from Orc pod-fleets, premium grade, traded fair. The receipts are in two languages and the better copy is theirs.","Furniture of a downsized noble house. The good pieces sold. These are the ones with the hidden drawers nobody found.","Seed grain for spring planting, duchy-subsidized, late, with three farming isles watching the horizon for it.","A modest crate of clockwork parts from Embercliff, manifested at a value that triples the insurance on the whole run.","Rope. Sixteen tons. The rigging trade calls this \"boring money\" and fights for the contract.","One sealed coffin, repatriation papers in order, escorted by a quiet cousin who never sleeps aboard.","Glassware from the southern kilns packed in last year’s newspapers — which a passenger keeps stealing to read.","Uniforms, naval pattern, two hundred sets, no insignia attached. The insignia ride in a separate, smaller, much better-guarded box.","Cheese wheels aging in transit, the shipper’s clever scheme: the route IS the cellar. The smell is the crew’s problem.","An orchard, nearly: forty saplings, root-balled, Glade-blessed, drinking fresh water the crew counts jealously.","Pig iron ingots stacked by a stevedore crew that clearly got paid by speed, not symmetry.","A carousel, complete, bought drunk at auction by a southern tavern keeper. The horses’ eyes follow you. Everyone agrees. No one says it.","Medical supplies, plague-flag priority, half donated, half invoiced at rates that explain the donations.","Marble, quarried, one block, immense — and a sculptor’s apprentice riding with it who talks to it through the tarp.","Sixty kegs of nails, and the carpenter’s guild stamp, and a shortage on the destination isle that someone arranged before placing this order.","A library, complete, willed to a school three duchies away, sorted by a system only the dead woman understood.","Fireworks for the harvest festival, stowed per regulation, which the bosun re-reads nightly like scripture.","Hides and pelts, Beastfolk-traded, tagged humanely sourced. The tags are honored. The price reflects the honor.","A strongbox, ducal courier grade, chained to the keel per contract. The chain is for show. The lock is not.","Dried mushrooms, Glade certified, culinary grade. One sack is medicinal grade. The cook has been warned. Twice.","Sailcloth, mill-fresh, white as a sin-free conscience, destined to be tarred black by buyers who don’t advertise.","An entire smithy: forge, anvils, tools, and a smith aboard who watches the lashings like they’re her children. They are. The children stayed behind with her sister.","Tea, compressed bricks, capital-bound, the new fashion. Last year’s fashion rides beneath it at a loss.","Two hundred empty barrels, cooper-fresh, bound for the cider isles. Riding high, rolling badly, smelling of oak and optimism.","Soap, lavender-pressed, luxury grade, and the whole crew smells like a duchess’s linen press by day three.","Survey instruments in fitted cases, crown property, with an inventory clerk’s seal on every latch and a discrepancy already in the count.","Salt cod and a passenger manifest of cats: a working pair of cargoes, the shipper notes, smugly.","A chandelier, dismantled, crystal by crystal, in four hundred numbered pouches, with diagram. Pouch 213 is missing. It has always been missing. The diagram says otherwise.","Roofing slate, storm-season demand, half pre-sold off the manifest before the ship even docks.","Wedding cargo: dress, gifts, wine, and a groom’s family heirloom sword that the bride’s family has politely asked be listed as \"decorative.\"","Ink, barreled, registry-office black. A second, smaller barrel of registry-office red rides under separate lock, signed for in triplicate.","Hops and brewing copper for a fort-town garrison whose morale, the requisition states plainly, depends on it.","A racing sloop’s spare hull riding as cargo on a freighter — the racing team’s rivals booked passage on the same freighter.","Pottery packed in straw, straw packed with fleas, fleas now packed with opinions about the crew.","Tax records, seven years, one duchy, transferring to capital archive under seal. Three parties have already inquired about this run’s route. The clerk aboard inquires why you ask.","Lamp oil in red-banded barrels, double-tariffed as hazardous, stowed aft, smoked near exactly once per voyage by exactly one new hire.","A menagerie, small: two peacocks, a tortoise, six rabbits, and a \"definitely a large cat\" in a crate with a noble’s crest and air holes punched from the inside.","Iron stoves, forty, with the foundry’s apology letter for the last shipment riveted, framed, to the first crate.","Honey in sealed jars and the beekeeper’s standing warning that exactly one jar per shipment ferments. Finding it early is a crew tradition now.","Schoolbooks, new curriculum, crown-approved, and a quiet crate of the old curriculum headed the same direction, paid in private coin.","An organ, chapel-sized, in eleven crates, with assembly instructions in a dead dialect and one organist aboard who claims he doesn’t need them.","Cooking pots, tinned, mundane beyond insult — and the smuggler’s favorite cargo class in three duchies for exactly that reason.","Festival masks, two gross, papier-mâché, harmless. The crew has worn them since day two. Watch duty is unsettling now.","Bricks of pressed seaweed fodder, Orc-traded, for livestock isles in the lean season. Smells like low tide’s grudge. Sells like gold.","A bathtub, copper, enormous, ducal commission, and standing orders that no one, NO ONE, naps in it. The orders are losing.","Charts, printed, new edition, embargoed until the first of the month, in a sealed crate the navigator circles like a gull.","Glue, hide-rendered, barreled, for the shipyards. The cooper’s dog refuses to board. The crew has noted this. The crew notes everything the dog does now.","Dried flowers, hundredweight bales, for the perfumers’ row. The hold smells like a funeral for someone very wealthy.","A jail door, oak and iron, custom-forged, with a delivery address that is currently a tavern and a buyer who says give it a month.","Boots. Military pattern, left boots only. The right boots travel separately. The quartermaster who designed this system has been promoted twice.","Telescope lenses in oil-paper, Embercliff-ground, and an optics apprentice who checks them at every jolt and has begun flinching preemptively.","Hay, compressed, an entire hold of it, and absolutely everyone aboard has been briefed on the words \"open flame\" until morale dipped.","A church window, stained glass, crated upright per the glazier’s sobbed instructions, depicting a saint nobody aboard can identify and one passenger won’t stop staring at.","Sugar loaves in blue paper, tariff-stamped. Blue paper without stamps rides in the next hold, and the supercargo’s answer to that is \"weather protection.\"","Anchors, four, replacement stock — and one fifth anchor, older, encrusted, crated, addressed to a museum, with a salvage writ the captain keeps in his own cabin.","Paper, mill-reams, registry white. Watermarked. The watermark is the cargo; the paper is incidental; the buyer is a printer of, officially, concert posters.","Wool, sacked, autumn clip, and a shepherd’s son riding along to see where it all goes, asking the kind of questions that improve contracts next year.","Vinegar, casked, and the cook’s ongoing war with the cooper over which barrels are vinegar and which are wine has entered its third voyage.","A piano (see also: every contract board in the Isles). This one is going DOWN a mountain. The monks waved it off cheerfully. They know something.","Tar, barreled, shipyard-bound, riding next to the sailcloth in a pairing the insurance assessor described, in writing, as \"thematic.\"","Relief supplies for a storm-struck isle: tools, tarps, dried stores — and the donor’s name painted on every crate at a size the storm survivors will discuss.","Coffee, green-bean sacks, the new vice of the capital’s clerk class, guarded accordingly: badly, by clerks.","One bell-buoy, decommissioned, sold to a tavern. It rings in swells. The crew has voted twice on cutting it loose. The captain owns shares in the tavern.","Locks and keys, separate crates, same maker, shipped together against every guild recommendation, because the buyer \"wants to watch them reunited.\"","Chalk, quarried, schoolhouse-grade, and the white handprints on every rail, line, and crewman’s back confirm the hold seal failed on day one.","Musical instruments for a fort-town band: brass, drums, and a triangle in its own fitted case, insured, individually, for reasons the manifest declines to give.","Dye in sealed drums, Glade-traded, the color the capital quietly abandoned — bought in bulk by a buyer betting on its return, or knowing something.","Horseshoes, crated, for isles with a combined total of nine horses. The blacksmith’s alternate theory involves Giants and is not entertained at the dinner table.","A lighthouse lens, first-order, irreplaceable, in a crate with railings, riding in a cradle the keeper’s guild built and blessed and bolted to the hull themselves.","Sand. White, fine, southern. For glassworks, officially. The hourglass-maker’s guild stamp on half the sacks tells the more interesting half of the story.","Tobacco, leaf-baled, and the customs stamps from three duchies layered on each bale like an argument the cargo won.","Armor stands, forty, empty, padded — the armor travels by another route, and a rival’s spy spent this whole voyage learning the shape of nothing.","A captured figurehead, hostile crew’s, riding as trophy cargo under harbor-law writ, and the old hands want it off the ship, off, OFF, at any port, at any price.","Quills, ink, ledgers, and sealing wax: a counting house in crates, relocating duchy by ducal invitation that reads, between its lines, like a summons.","Ballast stone, taking up paid cargo space, on a route where ballast stone awaits at the destination — and the supercargo’s smile, asked about it, could cut rope.","Toys, carved, painted, a workshop’s whole winter, festival-bound — and the carver aboard, retiring after this run, fixing each scuff each evening, slowly, like goodbye.","Wigs, court-grade, in climate crates. The capital’s humidity, the wigmaker explains to anyone trapped in conversation, is a conspiracy with named conspirators.","Doors. Just doors. Forty fine doors and no frames, bought by an isle that, per every chart and census, has thirty buildings. The carpenter aboard has a theory and a wager book.","One crate, ducal seal, manifest entry reading MISC., riding amidships under a guard rotation the captain set personally and pretends he didn’t.","Nothing. The hold is empty, clean-swept, and the run is paid at full freight by a shipper who required only that the ship sail this exact route, on this exact schedule, visibly.","The manifest itself: a single document case, courier-locked, containing the manifests of nine other ships — the true ones — traveling separately from their cargoes for reasons worth exactly what someone will pay to intercept this case."]},{"id":"trinkets","label":"Trinkets & Pocket Finds","die":"d100","color":"#a860d0","entries":["One playing card — the Knave of Anchors — from a deck pattern no chandler stocks.","A child’s drawing of a ship, signed with a smudge, folded to fit a coin purse.","A charge crystal shard, dead, warm to the touch anyway.","A tarnished locket containing a tiny painted portrait of a frowning pig.","Three feet of silk ribbon, jade-dyed, smelling faintly of a forest you’ve never visited.","A wooden duck, whittled, with one wing burned and the name AFTER scratched beneath.","A tavern token good for one drink at The Drowned Gull. The Gull burned down years ago. Tokens still circulate. Nobody knows who honors them. Somebody does.","A glass eye, hazel, well-made, with a scratch across the iris like a scar.","A ring of keys: four ordinary, one bone, one that hums in Fractal weather.","A pressed flower from the Verdant Glade that has not faded, browned, or quite stopped smelling of rain.","Dice, bone, weighted — but weighted to LOSE. A cheat for throwing games on purpose.","A love letter, unsent, addressed only \"To the lookout on the Patient Gull.\"","A fishhook of black iron, too large for any fish you’d want.","A miniature ship in a bottle. The ship inside has visible storm damage that wasn’t there last month.","A campaign medal from a battle no veteran will admit happened.","One gold tooth, set in a silver mount, on a watch chain. Conversation guaranteed.","A folded chart fragment showing one isle, no coordinates, and the word HOME.","A snuffbox containing no snuff: thread, two needles, a milk tooth, a coiled grey hair.","A whistle carved from a Marauder hull splinter — illegal in two duchies, lucky in all of them, silent to its owner and loud, sailors say, somewhere else.","A lady’s glove, left hand, kid leather, with a bullet hole through the palm and no stain.","A tin soldier, navy pattern, paint worn away everywhere a thumb would hold it.","Prayer beads of mixed make — replaced bead by bead over a lifetime; no two match; the string is new.","A pocketknife with seven previous owners’ initials and room, neatly left, for one more.","A theatre ticket, unused, front row, for a play that closed the night before its debut.","A small mirror that fogs from the wrong side.","A signal flag, pocket-sized, in a code no signal book lists. Old hands wince when shown it and won’t say why.","A bar of soap with a coin embedded at its center. The coin’s mint is the interesting part.","A sketch of you. Good likeness. Found before you met the artist. The paper is old.","A merchant’s sample case of buttons, one missing, with a reward notice glued in the lid for that exact button.","A clay bird that whistles when wind crosses it — pitched, an Avian will tell you uneasily, as a distress call.","A receipt for \"one favor, paid in full,\" stamped by a Nightshade counting house that doesn’t exist, for clients who insist it does.","Sixteen feet of string, knotted at irregular intervals. A Piscine reads it like a ledger and looks at you differently after.","A medicine bottle, stoppered, labeled DO NOT, in a doctor’s hurried hand.","A hatpin, eight inches, ruby-headed, sold \"lightly used\" by an estate clerk who wouldn’t meet your eye.","A perfect cube of obsidian, one inch, polished. Eastmarch quarriers carry them. They won’t say what they’re counting.","A betting slip from the fighting pits: long odds on a fighter named Tomorrow. Unredeemed.","A baby’s shoe, bronzed, used as a pipe-tamper by someone with reasons.","A monocle that shows everything slightly older — wood greyer, faces more lined, ships closer to their last voyage.","One earring, pearl, the pair to which features prominently in a famous portrait of a famous duchess.","A skeleton key broken in a lock — both halves, lock included, sawn out of its door.","A dance card from a capital ball, every line filled with the same name in the same hand.","A jar of buttons that don’t match any garment made in living memory.","A flask, engraved TO MY ENEMY, half full of genuinely excellent brandy.","A boatswain’s call that summons gulls. Only gulls. All the gulls.","A sealed letter with your name on it in handwriting you almost recognize. Postage paid. Decades-old stamp.","A scrimshawed mammoth tusk fragment showing a city skyline that matches no charted city.","A wedding band, inner inscription filed away with great care and incomplete success: \"...ver yours, V.\"","A pocket sundial, useless aboard ship, carried by sailors anyway. This one’s gnomon is bent to a specific, deliberate wrongness.","A tin of mints from a capital confectioner, sealed, fifty years old, allegedly still good. The bet stands at four silver.","A leather bookmark in the shape of an axolotl, Dryad-tooled, that always returns to the page you actually needed.","One domino — double-nine — from a set that, a Reptilian assures you flatly, has never existed. Reptilians count to eight-and-one.","A ship’s nail, bent into a ring, worn smooth. Wreck-iron rings are sold as luck. This one came with a name and the seller wouldn’t repeat it.","A pocket watch that runs perfectly and is set, immovably, four minutes ahead. Winds itself. Sets itself. Forgives nothing.","A tiny oil portrait of a cat in admiral’s uniform. The frame is worth more than most cats.","A bundle of incense from a Drifthaven night-market; burned, it smells of a summer noon, and old moon-folk pay dearly for it and burn it alone.","A cipher wheel, child’s toy grade, with one ring replaced by a craftsman who took it seriously.","A pewter spoon stamped with naval arms, the punishment for stealing which is recited fondly by its obvious thief.","A coil of wire that holds any shape it’s bent into — and is currently bent into a name.","An \"authentic Sundering relic,\" sold by the gross to pilgrims. This one is authentic. The seller doesn’t know it. It hums on the equinox.","A pair of loaded dice confiscated from a cheat, by a cheat, with a magistrate’s evidence tag and a postscript: \"lovely work though.\"","A handbill for a missing person, the description amended over the years in different inks as the missing person, presumably, aged.","A corkscrew shaped like a sea serpent, from a tavern that pulled it from a thousand bottles and finally lost it in a wager the keeper still talks about.","One chess pawn, ivory, promoted: a tiny paper crown glued on with care, decades ago, by someone who won.","A vial of sand that pours upward. Bottled Fractal-storm sand. Souvenir grade. Probably.","A laundry list, in a duke’s own hand, itemizing garments that tell the story of a very bad week.","A toy gondola of capital make, accurate down to the crest of its house — a house dissolved, struck from rolls, and unmentioned since before the toy’s buyer was born.","A bone fishhook in a velvet box presented like a jewel. To the Orc pods, it is one. The inscription dates it older than the duchy.","A bell the size of a thimble with no clapper, which Mushroom Folk lean toward as if it’s ringing.","A patchwork doll whose patches are, on inspection, a record: sailcloth, uniform serge, court silk, mourning crepe, in that order.","An iron coin from before the Sundering — illegal to deface, worthless to spend, and accepted with a nod at certain doors.","A ticket stub from the Celestial Gondola, first ring to fifth, punched in a pattern that gondoliers say isn’t a punch code. It’s a route.","A glass globe of grey haze that clears in lies and clouds in truth, or the reverse — the previous owner never decided and the haggling over it reveals more than it shows.","A folding knife with a blade of Marauder tooth. Cuts rope like rumor. Was absolutely not legally obtained. Has a waiting list.","A brass button stamped with the crest of the Silver Sword’s founding company — the original company, before the renaming nobody can document.","A child’s alphabet sampler stitched with a 27th letter, rendered carefully, as if the stitcher saw it daily.","A weathered NO TRESPASSING sign in Gnomish, which translates, properly, to \"PLEASE — we just finished fixing it.\"","A wad of stage money so well-made it has, per the arrest record folded around it, worked four times.","A tuning fork pitched to a note that makes charge crystals flicker — confiscated dock contraband, sold out the back, priced like a weapon, because.","A sealed deck of fortune cards, never opened, with a warning in three languages and a price scratched out and lowered, twice.","A dried starfish painted as a sheriff’s badge: \"Deputy of the Shallows.\" Children’s festival prize. There were only nine. Collectors exist. They are not children. Not anymore.","One hourglass, palm-sized, that runs the same duration every time and disagrees with every clock — sailors call the gap \"the lean,\" and trim their watches by it in bad sky.","A locket of woven hair from three heads, by tradition: one living, one dead, one \"as yet unmet.\"","A bar tab carved on a slat of the actual bar, settled, framed, and inscribed: \"the night the Cinderhouse paid US.\"","A bosun’s knot board — teaching tool, forty knots — with a forty-first added in different rope, unlabeled, that no instructor will tie twice.","A pressed-tin star from a fort-town festival, given for valor in a goose-catching incident the recipient’s gravestone mentions before their war record.","A small mirror in a case, its glass replaced with slate: a \"Drifthaven mirror,\" for people done with their reflection. They’re given, never bought. This one was sold. That’s the story.","An apothecary’s scale weight, one ounce, that weighs an ounce and a half — the fraud so old, so widespread, and so traceable to one foundry that magistrates collect the weights themselves.","A clay marble with a fly trapped at center, sold as amber to someone who knew better and bought it for the audacity.","A square of sailcloth bearing a tally: 100 strokes, struck through at 99.","A souvenir spyglass, capital-stamped, toy grade — through which, one owner in a hundred swears, the Isle of Giants is briefly, impossibly visible. The Jade Collection buys them all. Quietly. At toy prices.","A recipe card for \"Marauder stew (feeds 300, angers 1),\" annotated in a second hand: \"it worked.\"","A perfume bottle holding the smell of a specific harbor at dawn — bottled, the label claims, the morning before the harbor burned.","One die, twenty-sided, stone, older than the duchy, with worn faces — and the certainty, handling it, that it has decided things.","A pocket atlas, child’s edition, with the Isle of Giants printed plainly on page 9 — recalled, pulped, and worth a year’s wages to the right collector and a visit from the wrong one. Page 9 is intact.","A wax impression of a key, taken in a hurry, labeled in a dead man’s hand: \"if I’m right.\"","A trick coin: heads on both sides, and a third side, discovered only on edge, in low light, once, by everyone who has ever owned it.","A bottle of harbor water labeled with a date five years out. Salvager’s humor — bottling \"future wrecks.\" This bottle’s label, dated last spring, names a ship that sank last spring. The salvager retired.","A small brass plaque, unscrewed from something, reading: DONATED BY A FRIEND OF THE CITY, WHO ASKS ONLY THAT YOU NOT LOOK FOR HER.","A blank page, good paper, deckle-edged, kept folded in an oilskin wrap by someone who clearly treasured it. Held to candlelight, firelight, moonlight: nothing. Held up in Fractal rain — well. Nobody’s tried. Whoever wrapped it that carefully knew something."]},{"id":"fractalrain","label":"Fractal Rain Effects","die":"d10","color":"#6080d0","entries":["Mild crystalline precipitation — no mutation risk, brief and beautiful.","Light Rain — cosmetic mutations: new pigmentation, texture change on exposed creatures.","Moderate Rain — exposed creatures roll CON save DC 12 or gain a minor permanent trait.","Heavy Rain — all unprotected creatures save DC 15 or suffer significant physical mutation.","Rain carries whispers — listeners make WIS save DC 13 or become briefly obsessed with what they heard.","Rain forms shapes — silhouettes of people, places, or things the witness has never seen.","Crystalline structures precipitate and harden on contact. Razor-sharp difficult terrain until cleared.","Rain affects only one creature, targeting them specifically and apparently deliberately.","Rain reverses — rises from the ground and isle surface, pulling loose objects briefly skyward.","Void-touched Rain — black, silent, leaves no trace. Exposed creatures lose memory of the last hour."]}];
_RTABLES.length = 0;
_compTables.forEach(function(t){ _RTABLES.push(t); });

// Closure-scoped state for tables tab (avoids main-script let scope issues)
var _rt = { activeId: _RTABLES[0].id, rolled: -1 };

window._rgenRenderTables = function(body) {
  var tbl = _RTABLES.find(function(t){ return t.id===_rt.activeId; }) || _RTABLES[0];
  var c = tbl.color;
  var selOpts = _RTABLES.map(function(t){
    return '<option value="'+t.id+'"'+(t.id===_rt.activeId?' selected':'')+'>'+t.label+' ('+t.die+')</option>';
  }).join('');
  var rolled = _rt.rolled;
  var resultHtml = '';
  if (rolled >= 0 && tbl.entries[rolled]) {
    var num = String(rolled+1).padStart(2,'0');
    resultHtml = '<div style="margin-bottom:.4rem;padding:.35rem .55rem;background:'+c+'1a;border:1px solid '+c+'55;border-radius:7px;display:flex;gap:.5rem;align-items:flex-start">'
      +'<span style="font-family:var(--mono);font-size:.72rem;color:'+c+';flex-shrink:0;padding-top:.05rem">'+tbl.die+': '+num+'</span>'
      +'<span style="font-size:.82rem;color:#f0e8d0;font-style:italic;line-height:1.45;text-wrap:pretty">'+tbl.entries[rolled]+'</span>'
      +'</div>';
  }
  var rows = tbl.entries.map(function(e,i){
    var num   = String(i+1).padStart(2,'0');
    var hit   = (i === rolled);
    var bg    = hit ? c+'28' : 'rgba(255,255,255,.04)';
    var bl    = hit ? '2px solid '+c : '2px solid rgba(255,255,255,.08)';
    return '<div onclick="window._rtCopyRow('+i+')" title="Click to copy"'
      +' style="display:flex;gap:.45rem;padding:.3rem .45rem;border-radius:5px;cursor:pointer;background:'+bg+';border-left:'+bl+';transition:background .12s"'
      +' onmouseover="this.style.background=\''+c+'18\'" onmouseout="this.style.background=\''+bg+'\'">  '
      +'<span style="font-family:var(--mono);font-size:.65rem;color:'+(hit?c:'rgba(255,255,255,.22)')+';flex-shrink:0;line-height:1.55;min-width:1.4rem">'+num+'</span>'
      +'<span style="font-size:.8rem;color:'+(hit?'#f0e8d0':'#b0a898')+';line-height:1.5;text-wrap:pretty">'+e+'</span>'
      +'</div>';
  }).join('');
  body.innerHTML = '<div style="display:flex;gap:.4rem;flex-wrap:wrap;margin-bottom:.5rem;align-items:center">'
    +'<select id="rtable-sel" onchange="window._rtSelectTable(this.value)" style="background:rgba(255,255,255,.07);color:#ccc;border:1px solid rgba(255,255,255,.18);border-radius:5px;padding:.22rem .4rem;font-size:.75rem;font-family:inherit;outline:none;flex:1;min-width:0">'+selOpts+'</select>'
    +'<button onclick="window._rtRoll()" style="padding:.22rem .65rem;font-size:.78rem;border-radius:5px;cursor:pointer;border:1px solid '+c+'66;background:'+c+'18;color:'+c+';font-family:inherit;flex-shrink:0">🎲 Roll '+tbl.die+'</button>'
    +'</div>'
    +'<div id="rtable-rolled">'+resultHtml+'</div>'
    +'<div id="rtable-rows" style="display:flex;flex-direction:column;gap:.18rem">'+rows+'</div>';
};
window._rtSelectTable = function(id) {
  _rt.activeId = id; _rt.rolled = -1;
  var body = document.getElementById('rgen-body');
  if (body) _rgenRenderTables(body);
};
window._rtRoll = function() {
  var tbl = _RTABLES.find(function(t){ return t.id===_rt.activeId; }) || _RTABLES[0];
  _rt.rolled = Math.floor(Math.random() * tbl.entries.length);
  var body = document.getElementById('rgen-body');
  if (body) _rgenRenderTables(body);
};
window._rtCopyRow = function(i) {
  var tbl = _RTABLES.find(function(t){ return t.id===_rt.activeId; }) || _RTABLES[0];
  if (navigator.clipboard && tbl.entries[i]) navigator.clipboard.writeText(tbl.entries[i]);
};

// ── 4. Names tab (with Full Name toggle) ─────────────────────
window._rgenRenderNames = function(body) {
  body.innerHTML = `
    <div style="display:flex;flex-wrap:wrap;gap:.4rem;align-items:center;margin-bottom:.5rem">
      <select id="npc-race-sel" style="background:rgba(255,255,255,.07);color:#ccc;border:1px solid rgba(255,255,255,.18);border-radius:5px;padding:.22rem .4rem;font-size:.78rem;font-family:inherit;outline:none">
        <option value="gnome">Gnome</option><option value="dwarf">Dwarf</option>
        <option value="human">Human</option><option value="reptilian">Reptilian</option>
        <option value="celestial">Celestial</option><option value="shade">Shade</option>
        <option value="dryad">Dryad</option><option value="piscine">Piscine</option>
        <option value="elemental">Elemental</option><option value="voidwalker">Void Walker</option>
        <option value="dragonkin">DragonKin</option><option value="fellfolk">Fell Folk</option>
        <option value="amphibian">Amphibian</option><option value="avian">Avian</option>
        <option value="beastfolk">Beastfolk</option><option value="mushroomfolk">Mushroom Folk</option>
        <option value="invertebrate">Invertebrate</option><option value="fairy">Fairy</option>
        <option value="giant">Giant</option><option value="orc">Orc</option>
      </select>
      <select id="npc-gender-sel" style="background:rgba(255,255,255,.07);color:#ccc;border:1px solid rgba(255,255,255,.18);border-radius:5px;padding:.22rem .4rem;font-size:.78rem;font-family:inherit;outline:none">
        <option value="any">Any</option><option value="masc">Masc</option><option value="fem">Fem</option>
      </select>
      <label style="display:flex;align-items:center;gap:.3rem;font-size:.72rem;color:#aaa;cursor:pointer;flex-shrink:0">
        <input type="checkbox" id="npc-fullname" style="accent-color:#c9a84c"> Full name
      </label>
      <button onclick="_rollNPCNames()" style="padding:.22rem .6rem;font-size:.78rem;border-radius:5px;cursor:pointer;border:1px solid rgba(201,168,76,.4);background:rgba(201,168,76,.14);color:#c9a84c;font-family:inherit">🎲 Roll</button>
    </div>
    <div id="npc-names-output" style="display:grid;grid-template-columns:1fr 1fr;gap:.28rem"></div>`;
};
window._rollNPCNames = function() {
  var race   = (document.getElementById('npc-race-sel')||{}).value||'human';
  var gender = (document.getElementById('npc-gender-sel')||{}).value||'any';
  var full   = !!(document.getElementById('npc-fullname')||{}).checked;
  var pool   = _NPC_NAMES[race] || _NPC_NAMES.human;
  var first  = gender==='masc' ? [...pool.masc] : gender==='fem' ? [...pool.fem] : [...pool.masc,...pool.fem];
  var chosen = _rgenPick(first, 6);
  var results = chosen.map(function(n){
    if (full && pool.family && pool.family.length)
      return n + ' ' + pool.family[Math.floor(Math.random()*pool.family.length)];
    return n;
  });
  var el = document.getElementById('npc-names-output');
  if (!el) return;
  el.innerHTML = results.map(function(n){
    var safe = n.replace(/'/g,"&#39;");
    return '<div onclick="navigator.clipboard&&navigator.clipboard.writeText(this.dataset.v)" data-v="'+safe+'" title="Click to copy"'
      +' style="padding:.3rem .5rem;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:5px;font-size:.85rem;color:#e0d6c0;cursor:pointer;text-align:center;border-left:2px solid rgba(201,168,76,.4)"'
      +' onmouseover="this.style.background=\'rgba(201,168,76,.12)\'" onmouseout="this.style.background=\'rgba(255,255,255,.05)\'">'+n+'</div>';
  }).join('');
};

// ── 5. Random Tables lore entry ──────────────────────────────
// NOTE: runs before loadState() — NEVER call saveState() here.
